// CONFIGURATION - Change this value to adjust column width
const COLUMN_WIDTH = 5; // Adjust this number to change spacing for all columns

// Assume input is an array of JSON objects (rows)
const items = $input.all();
if (items.length === 0) return [];

// Get all unique headers from all items (in case some items have different keys)
const allHeaders = new Set();
items.forEach(item => {
  Object.keys(item.json).forEach(key => allHeaders.add(key));
});
const headers = Array.from(allHeaders);

// Helper function to pad values to fixed width
function padValue(value, width) {
  const str = String(value);
  return str.length >= width ? str : str + ' '.repeat(width - str.length);
}

// Create CSV header row with padding
const paddedHeaders = headers.map(header => padValue(header, COLUMN_WIDTH));
const csvRows = [paddedHeaders.join(',')];

// Process each item
for (const item of items) {
  const row = headers.map(header => {
    let value = item.json[header] || ''; // Handle missing values

    // Handle different data types and escape CSV special characters
    if (value === null || value === undefined) {
      value = '';
    } else if (typeof value === 'object') {
      value = JSON.stringify(value);
    } else {
      value = String(value);
    }

    // Escape quotes and wrap in quotes if contains comma, quote, or newline
    if (value.includes(',') || value.includes('"') || value.includes('\n')) {
      value = '"' + value.replace(/"/g, '""') + '"';
    }

    // Pad the value to maintain consistent column width
    return padValue(value, COLUMN_WIDTH);
  });

  csvRows.push(row.join(','));
}

return [{ json: { text: csvRows.join('\n') } }];

// Get the input string from previous node
const inputString = $input.first().json.inputString;

try {
  // Step 1: Remove code block markers if present
  const cleanString = inputString
    .replace(/^``````json marker
    .replace(/\s*`````` marker
    .trim();                        // Remove extra whitespace

  // Step 2: Parse the cleaned string
  const parsedJson = JSON.parse(cleanString);

  // Return parsed JSON as new item
  return [{
    json: parsedJson
  }];

} catch (error) {
  // Handle parsing errors
  return [{
    json: {
      error: "Failed to parse JSON",
      details: error.message,
      originalString: inputString,
      cleanedString: cleanString // Optional: helps debugging
    }
  }];
}

// Get all incoming items from the previous node
const items = $input.all();

// Loop through each item (n8n processes data in batches)
for (const item of items) {
  // --- IMPORTANT ---
  // Assuming your input text is in a field called 'rawText'.
  // If your field is named something else, change 'rawText' below.
  const inputText = item.json.rawText;

  if (typeof inputText !== 'string' || !inputText) {
    // If the field doesn't exist or is empty, just continue
    item.json.error = "Input field 'rawText' is missing or not a string.";
    continue;
  }

  try {
    // Find the first occurrence of '{', which marks the start of the actual JSON object.
    const jsonStartIndex = inputText.indexOf('{');

    if (jsonStartIndex === -1) {
      // Handle cases where no JSON object is found in the text
      throw new Error("Could not find the start of a JSON object ('{').");
    }

    // Extract the substring that is the actual JSON data.
    const jsonString = inputText.substring(jsonStartIndex);

    // Parse the clean string into a JavaScript object.
    const parsedJson = JSON.parse(jsonString);

    // Add the new, parsed object to a field called 'properJson' in the output.
    item.json.properJson = parsedJson;

  } catch (error) {
    // If parsing fails for any reason, add an error message to the output
    // so you can debug it easily in the n8n workflow.
    item.json.error = `Failed to parse JSON: ${error.message}`;
  }
}

// Return the modified items to be used by the next node in the workflow.
return items;
